\begin{document}
\maketitle

\begin{abstract}
Monstrous moonshine attaches to each element $g$ of a finite group $G$ acting on a graded space a
generating function $T_g(q)=\sum_n \tr(g\mid V_n)q^n$, and asserts deep modularity properties of
these series. This paper isolates the part of that architecture which is unconditionally true for
every finite group acting on every graded finite set, and develops it into a complete quantitative
theory. Working with the permutation-character specialization $T_g(q)=\sum_n |X_n^g|q^n$, we prove:
a \emph{moment hierarchy} identifying $\sum_{g\in G}|X^g|^k$ with $|G|$ times the number of orbits
on $k$-tuples, of which Burnside's lemma is the case $k=1$; superadditivity
$\#(X/G)^k\le\#(X^k/G)$ with a rigidity theorem characterizing the trivial action; a universal
\emph{Bell floor} $B_k|G|\le\sum_g|X^g|^k$ for $k\le|X|$, with $B_k$ the $k$-th Bell number; a
\emph{Bell criterion} stating that the floor is attained exactly for $k$-transitive actions, so a
single integer moment decides a classical permutation-group property; a \emph{fibre spectrum}
refinement expressing the Bell defect $\sum_g|X^g|^k-B_k|G|$ exactly as $|G|\sum_P(m_P-1)$, where
$m_P$ counts orbits with kernel pattern $P$; a \emph{moment inversion theorem} showing that for
actions on sets of size at most $N$ the multiset $\{|X^g|:g\in G\}$ is determined by the moments
$k\le N$ and by no shorter range, together with an explicit Klein-four example showing that the
trace distribution is \emph{not} a complete invariant of the action; and, on the analytic side, a
complete analysis of the ``product over all classes'' slogan: a product of $m$ series of order $-1$
at the cusp has order exactly $-m$, renormalized products realize precisely the order-$0$ series,
factorizations are never unique, and no permutation-invariant aggregate of $m\ge2$ series is
injective, while an explicit label-remembering aggregate is.
\end{abstract}

\section{Introduction}

\subsection{The moonshine template}

Monstrous moonshine begins with a graded module $V=\bigoplus_n V_n$ for the Monster simple group $M$
and, for each $g\in M$, the McKay--Thompson series
\[
  T_g(q)=\sum_{n\ge-1}\tr(g\mid V_n)q^n=q^{-1}+O(q),
\]
whose class $T_1$ is the normalized modular $j$-invariant $J(q)=j(q)-744$. Three features of that
construction are logically independent of the modularity miracle: element-indexing (one series per
conjugacy class), averaging (the mean of the family is a canonical quotient object), and grading
(everything happens coefficientwise in a formal $q$-expansion).

Our thesis is that these three features, and a surprising amount of quantitative structure built on
them, hold for \emph{every} finite group acting on \emph{every} graded finite set --- and that the
resulting theory is sharp, with explicit equality cases, explicit defects, and explicit
counterexamples marking its boundaries. Conversely the genuinely analytic features of moonshine do
not survive, and we make precise exactly where and why the naive extrapolations break.

\subsection{The combinatorial specialization}

Let $G$ be a finite group acting on a finite set $X$. The most elementary trace available is the
permutation character $\chi_X(g)=|X^g|=\#\{x\in X: g\cdot x=x\}$, the character of $\mathbb{C}[X]$.
For a graded action, a family $(X_n)_{n\ge0}$ of finite $G$-sets, one obtains a formal trace series
\[
  T_g(q)=\sum_{n\ge0}|X_n^g|\,q^n\in\mathbb{Z}[[q]].
\]
Since $x\mapsto h\cdot x$ is a bijection $X^{g}\to X^{hgh^{-1}}$, each coefficient and hence each
series is a class function: the family $(T_g)_{g\in G}$ descends to conjugacy-class data exactly as
the McKay--Thompson family does.

\section{The moment hierarchy}

Throughout, $G$ is a finite group and $X$ a finite $G$-set; $X^k$ denotes the set of maps
$\{1,\dots,k\}\to X$ with the diagonal action.

\begin{lemma}[Fixed points of the diagonal action]\label{lem:diag}
For every $g\in G$ and $k\ge0$, restriction to coordinates gives a bijection
$(X^k)^g\cong(X^g)^k$; in particular $|(X^k)^g|=|X^g|^k$.
\end{lemma}

\begin{proof}
A tuple $f$ is fixed by $g$ if and only if $g\cdot f(i)=f(i)$ for every $i$, i.e.\ if and only if
every coordinate lies in $X^g$.
\end{proof}

\begin{theorem}[Moment hierarchy]\label{thm:moment}
For every $k\ge0$,
\[
  \sum_{g\in G}|X^g|^{k}=|G|\cdot\#\bigl(X^{k}/G\bigr).
\]
\end{theorem}

\begin{proof}
Burnside's orbit-counting lemma applied to the $G$-set $X^k$ gives
$\sum_g|(X^k)^g|=|G|\cdot\#(X^k/G)$; substitute Lemma~\ref{lem:diag}.
\end{proof}

For $k=1$ this is Burnside's lemma $\sum_g|X^g|=|G|\,|X/G|$; for $k=2$ it says that
$\frac1{|G|}\sum_g|X^g|^2$ is the rank of the permutation action, i.e.\ the number of orbits on
ordered pairs.

\paragraph{Graded form.} Applying Theorem~\ref{thm:moment} in each grade, the coefficientwise
$k$-th moment of the trace family is a generating function of orbit counts,
\[
  \sum_{n\ge0}\Bigl(\sum_{g\in G}|X_n^g|^k\Bigr)q^n=|G|\sum_{n\ge0}\#\bigl(X_n^k/G\bigr)q^n,
\]
whose case $k=1$ is the moonshine average
$\sum_{g\in G}T_g(q)=|G|\,O(q)$ with $O(q)=\sum_{n\ge0}|X_n/G|q^n$.

\begin{proposition}[Superadditivity]
For every $k$, $\#(X/G)^k\le\#(X^k/G)$.
\end{proposition}

\begin{proof}
Choose one representative per orbit of $X$; distinct $k$-tuples of representatives lie in distinct
orbits of $X^k$, because the induced tuple of orbits is a $G$-invariant of a tuple.
\end{proof}

\begin{theorem}[Rigidity at $k=2$]
$\#(X/G)^2=\#(X^2/G)$ if and only if $G$ acts trivially on $X$.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:moment} the assertion is
$\bigl(\frac1{|G|}\sum_g|X^g|\bigr)^2=\frac1{|G|}\sum_g|X^g|^2$, i.e.\ the vanishing of the
variance of $g\mapsto|X^g|$, i.e.\ constancy of that function. Since $|X^1|=|X|$, constancy forces
$X^g=X$ for all $g$. Conversely a trivial action has $\#(X^k/G)=|X|^k=\#(X/G)^k$.
\end{proof}

A quantitative refinement holds: the Cauchy--Schwarz defect
$|G|\sum_g|X^g|^2-(\sum_g|X^g|)^2$ bounds, for any single element $g_0$, the deviation of
$|X^{g_0}|$ from the mean $|X/G|$. Moreover, for any single $k\ge1$, the action is free precisely
when $\sum_g|X^g|^k=|X|^k$; for the left regular action $\#(G^{k+1}/G)=|G|^{k}$.

\section{Kernel patterns, Bell numbers, and $k$-transitivity}

\begin{definition}[Pattern]
A \emph{pattern} on $\{1,\dots,k\}$ is a map $p:\{1,\dots,k\}\to\{1,\dots,k\}$ with $p(i)\le i$ and
$p(p(i))=p(i)$ for all $i$; equivalently, a restricted growth function. Write $\Pat(k)$ for the set
of patterns.
\end{definition}

\begin{proposition}
Patterns on $\{1,\dots,k\}$ correspond bijectively to set partitions of $\{1,\dots,k\}$, via
$p(i)=\min(\text{block of }i)$. Hence $|\Pat(k)|=B_k$, the $k$-th Bell number; the first values are
$B_0,\dots,B_5=1,1,2,5,15,52$.
\end{proposition}

\begin{definition}[Kernel pattern]
For $f:\{1,\dots,k\}\to X$ put $\kerpat(f)(i)=\min\{j: f(j)=f(i)\}$.
\end{definition}

\begin{lemma}\label{lem:kerpat}
(a) $f(\kerpat(f)(i))=f(i)$ and $\kerpat(f)(i)\le i$; (b) $\kerpat(f)\in\Pat(k)$;
(c) $\kerpat(f)(i)=\kerpat(f)(j)\iff f(i)=f(j)$; (d) $f$ is injective iff $\kerpat(f)=\mathrm{id}$;
(e) $\kerpat(g\cdot f)=\kerpat(f)$ for every $g\in G$.
\end{lemma}

\begin{proof}
(a), (b) are immediate. (c) If $f(i)=f(j)$ the defining sets coincide; conversely equal minima give
$f(i)=f(\kerpat(f)(i))=f(\kerpat(f)(j))=f(j)$ by (a). (d) follows from (c). (e) $g$ acts by a
bijection, so $g\cdot f(j)=g\cdot f(i)\iff f(j)=f(i)$.
\end{proof}

By (e) the kernel pattern descends to a map
$\pi_k: X^k/G\to\Pat(k)$, $\pi_k([f])=\kerpat(f)$.

\begin{lemma}[Injective extension]\label{lem:ext}
Let $|X|\ge k$, let $L\subseteq\{1,\dots,k\}$, and let $f$ be injective on $L$. Then some globally
injective $u:\{1,\dots,k\}\to X$ satisfies $u|_L=f|_L$.
\end{lemma}

\begin{proof}
Extend one index at a time: if $u$ is injective on a set $S$ of size $<k$, then $|u(S)|<k\le|X|$,
so an unused point of $X$ is available for the next index.
\end{proof}

\begin{proposition}[Surjectivity]\label{prop:surj}
If $k\le|X|$ then $\pi_k$ is surjective; consequently $B_k\le\#(X^k/G)$.
\end{proposition}

\begin{proof}
Given $p\in\Pat(k)$, let $L$ be its set of fixed points (block leaders). By Lemma~\ref{lem:ext}
choose $u$ injective and put $f=u\circ p$. Since $u$ is injective, $f(i)=f(j)\iff p(i)=p(j)$, and
$p(i)\le i$ with $p\circ p=p$ shows the block minima agree, so $\kerpat(f)=p$ by
Lemma~\ref{lem:kerpat}(c).
\end{proof}

\begin{corollary}[Bell floor]\label{cor:bellfloor}
If $k\le|X|$ then $B_k\cdot|G|\le\sum_{g\in G}|X^g|^{k}$ for every finite group $G$ acting on $X$.
\end{corollary}

\begin{definition}
The action is \emph{$k$-transitive} if for all injective $f,f':\{1,\dots,k\}\to X$ there is $g\in G$
with $g\cdot f=f'$.
\end{definition}

\begin{theorem}[Same pattern implies same orbit]\label{thm:samepattern}
Let $k\le|X|$ and suppose the action is $k$-transitive. If $\kerpat(f)=\kerpat(f')$ then $f$ and
$f'$ lie in the same $G$-orbit.
\end{theorem}

\begin{proof}
Let $p$ be the common pattern and $L$ its set of fixed points; by Lemma~\ref{lem:kerpat}(c) both $f$
and $f'$ are injective on $L$. Extend by Lemma~\ref{lem:ext} to injective $u,u'$ agreeing with $f$,
resp.\ $f'$, on $L$, and take $g$ with $g\cdot u=u'$. For each $i$ we have $p(i)\in L$ and
$f(i)=f(p(i))=u(p(i))$, $f'(i)=u'(p(i))$, hence $g\cdot f(i)=f'(i)$.
\end{proof}

\begin{theorem}[Bell criterion]\label{thm:bellcrit}
Let $G$ act on a finite set $X$ with $k\le|X|$. The following are equivalent:
\begin{enumerate}
  \item the action is $k$-transitive;
  \item $\pi_k$ is injective;
  \item $\#(X^k/G)=B_k$;
  \item $\sum_{g\in G}|X^g|^{k}=B_k\cdot|G|$.
\end{enumerate}
\end{theorem}

\begin{proof}
(1)$\Rightarrow$(2) is Theorem~\ref{thm:samepattern}. (2)$\Rightarrow$(1): injective tuples all have
pattern $\mathrm{id}$, so injectivity of $\pi_k$ makes them a single orbit. (2)$\Leftrightarrow$(3):
$\pi_k$ is a surjection of finite sets by Proposition~\ref{prop:surj}, hence injective iff domain
and codomain have equal size, and $|\Pat(k)|=B_k$. (3)$\Leftrightarrow$(4) is
Theorem~\ref{thm:moment}.
\end{proof}

\begin{corollary}
For $|X|$ large enough: the first moment equals $|G|$ iff the action is transitive; the second
equals $2|G|$ iff $2$-transitive; the third equals $5|G|$ iff $3$-transitive; and in general the
$k$-th equals $B_k|G|$ iff $k$-transitive.
\end{corollary}

\begin{corollary}[Symmetric groups]
$S_n$ on $n$ points is $k$-transitive for all $k\le n$, hence
$\sum_{\sigma\in S_n}|\fix(\sigma)|^{k}=B_k\cdot n!$ for $k\le n$: the number of fixed points of a
uniform random permutation has the moments of a Poisson$(1)$ variable up to order $n$.
\end{corollary}

\begin{proposition}[Monotone hierarchy]
If $k+1\le|X|$ and the action is $(k+1)$-transitive, it is $k$-transitive; hence extremality of the
$(k+1)$-st moment forces extremality of all lower moments.
\end{proposition}

If every grade of a graded $G$-set is $k$-transitive, the coefficientwise $k$-th moment of the trace
family is the constant series with every coefficient equal to $B_k|G|$.

\section{The fibre spectrum and the exact Bell defect}

\begin{definition}
For $P\in\Pat(k)$ let $m_P=\#\pi_k^{-1}(P)$, the number of orbits of $k$-tuples with kernel pattern
$P$.
\end{definition}

\begin{proposition}\label{prop:fibre}
$\sum_{P\in\Pat(k)}m_P=\#(X^k/G)$, and if $k\le|X|$ then $m_P\ge1$ for every $P$.
\end{proposition}

\begin{theorem}[Fibrewise transitivity criterion]
If $k\le|X|$, the action is $k$-transitive if and only if $m_P=1$ for every pattern $P$.
\end{theorem}

\begin{theorem}[Exact Bell defect]\label{thm:defect}
Let $k\le|X|$. Then
\[
  D_k:=\sum_{g\in G}|X^g|^{k}-B_k|G|=|G|\sum_{P\in\Pat(k)}(m_P-1)\;\ge\;0,
\]
with $D_k=0$ exactly when the action is $k$-transitive.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:moment} and Proposition~\ref{prop:fibre},
$\sum_g|X^g|^k=|G|\sum_P m_P$; writing $m_P=1+(m_P-1)$ and summing over the $B_k$ patterns gives
$\sum_P m_P=B_k+\sum_P(m_P-1)$.
\end{proof}

Thus the Bell defect is a census of the extra orbits, resolved pattern by pattern. For $C_n$ acting
on $n$ points and $k=2$, the diagonal pattern has $m=1$ and the distinct-coordinate pattern splits
into $n-1$ orbits, giving $D_2=n(n-2)$.

\section{Moments determine the trace distribution}

\begin{theorem}[Moment inversion]\label{thm:inversion}
Let $a:I\to\mathbb{N}$ and $b:J\to\mathbb{N}$ be functions on finite sets, both bounded by $N$. If
$\sum_{i}a(i)^k=\sum_j b(j)^k$ for all $0\le k\le N$, then $a$ and $b$ have the same value multiset.
Conversely, equal value multisets give equal power sums for every $k$.
\end{theorem}

\begin{proof}
Let $c_v=\#\{i:a(i)=v\}$ and $d_v=\#\{j:b(j)=v\}$ for $0\le v\le N$. Partitioning by value,
$\sum_i a(i)^k=\sum_{v}c_v v^k$ and likewise for $b$. Over $\mathbb{Q}$ this is $Mc=Md$ with
$M=(v^k)_{0\le k,v\le N}$, the transpose of a Vandermonde matrix with distinct nodes
$0,1,\dots,N$, whose determinant $\prod_{u<v}(v-u)$ is nonzero; hence $c=d$.
\end{proof}

\begin{theorem}[Sharpness]
The range $k\le N$ cannot be shortened: $a=(0,2)$ and $b=(1,1)$ are bounded by $N=2$ and have equal
power sums for $k\le1$ but different value multisets.
\end{theorem}

\begin{definition}
The \emph{trace distribution} of a finite $G$-action on $X$ is the multiset
$\mathcal{T}(G,X)=\{|X^g|:g\in G\}$ (with multiplicities).
\end{definition}

\begin{theorem}[Trace distribution versus orbit counts]\label{thm:tracedist}
Let $G$ be finite and $X,Y$ finite $G$-sets with $|X|,|Y|\le N$. Then
$\mathcal{T}(G,X)=\mathcal{T}(G,Y)$ if and only if $\#(X^k/G)=\#(Y^k/G)$ for all $k\le N$, if and
only if $\#(X^k/G)=\#(Y^k/G)$ for all $k$.
\end{theorem}

\begin{proof}
Fixed-point counts are bounded by $N$. By Theorem~\ref{thm:moment} the orbit counts are the power
sums divided by $|G|$; apply Theorem~\ref{thm:inversion} in one direction and its converse half in
the other, the latter also yielding the propagation from $k\le N$ to all $k$.
\end{proof}

\begin{corollary}
Equal trace distributions imply: the number of group elements with exactly $v$ fixed points agrees
for every $v$ (in particular the number of fixed-point-free elements); the orbit counts $|X/G|$ and
$|Y/G|$ agree; and by Theorem~\ref{thm:bellcrit} the whole $k$-transitivity spectrum agrees.
\end{corollary}

\begin{theorem}[The trace distribution is not a complete invariant]\label{thm:klein}
Let $V=S_2\times S_2$ act on a two-point set $X$ through its first factor and on a two-point set $Y$
through its second. Then $\mathcal{T}(V,X)=\mathcal{T}(V,Y)$ and $\#(X^k/V)=\#(Y^k/V)$ for all $k$,
yet $X$ and $Y$ are not isomorphic as $V$-sets.
\end{theorem}

\begin{proof}
The factor swap $\sigma(g_1,g_2)=(g_2,g_1)$ is a bijection of $V$ with $|X^g|=|Y^{\sigma(g)}|$, so
the value multisets agree and Theorem~\ref{thm:tracedist} applies. An equivariant bijection
$e:X\to Y$ would satisfy $e(g\cdot x)=g\cdot e(x)$, which fails for $g=(\text{swap},1)$: this
element moves both points of $X$ and fixes both points of $Y$.
\end{proof}

\section{Laurent normalization, pole orders, and aggregation}

Model $q$-expansions as formal Laurent-type series $F=\sum_{n\in\mathbb{Z}}c_nq^n$ with integer
coefficients and well-ordered support, and let $\ord(F)$ be the least exponent with $c_n\ne0$.

\begin{definition}
$F$ is \emph{McKay--Thompson normalized} if $\ord(F)=-1$.
\end{definition}

Normalized series are abundant: $q^{-1}+c$ and $aq^{-1}$ ($a\ne0$) are normalized. Trace series of a
graded action become normalized after prepending the polar term:
$\widehat T_g(q)=q^{-1}+\sum_{n\ge0}|X_n^g|q^n$, and the averaging identity persists at this level.

\begin{lemma}
For a finite family of nonzero series, $\ord(\prod_i f_i)=\sum_i\ord(f_i)$.
\end{lemma}

\begin{theorem}[Pole-order obstruction]\label{thm:pole}
If $f_1,\dots,f_m$ are normalized then $\ord(\prod_i f_i)=-m$. In particular the product is never
holomorphic at the cusp for $m\ge1$, and a product of $194$ normalized series --- one per Monster
conjugacy class --- has a pole of order exactly $194$. Multiplying by $q^m$ restores order $0$.
\end{theorem}

\begin{theorem}[Renormalized products realize exactly the order-zero series]\label{thm:surj}
Let $m\ge1$ and let $F$ satisfy $\ord(F)=0$. Then there are normalized $f_1,\dots,f_m$ with
$q^m\prod_i f_i=F$. Hence the image of the renormalized-product map is precisely the set of
order-$0$ series.
\end{theorem}

\begin{proof}
Put $f_1=q^{-1}F$ and $f_i=q^{-1}$ for $i\ge2$; all factors have order $-1$ and
$q^m\cdot q^{-1}F\cdot q^{-(m-1)}=F$. The converse inclusion is Theorem~\ref{thm:pole}.
\end{proof}

\begin{theorem}[Non-uniqueness]
Every order-$0$ series has at least two distinct factorizations as a renormalized product of two
normalized series: if $q^2f_1f_2=F$ then also $q^2(-f_1)(-f_2)=F$, and normalized series are
nonzero, so the two families differ.
\end{theorem}

\begin{theorem}[No injective symmetric aggregate]\label{thm:sym}
Let $m\ge2$ and let $A$ map families of $m$ series to a single series with
$A(f\circ\sigma)=A(f)$ for every permutation $\sigma$ of the labels. Then $A$ is not injective.
\end{theorem}

\begin{proof}
Take $f_1=q^{-1}$ and $f_2=\dots=f_m=2q^{-1}$. Transposing the first two entries gives a different
family with the same $A$-value.
\end{proof}

\begin{corollary}
The product aggregate is non-injective for every $m\ge2$, since multiplication is commutative: the
information loss of ``multiply everything together'' is structural, not an artefact of an example.
\end{corollary}

\begin{theorem}[A faithful, necessarily labelled aggregate]
Fix $m\ge1$ and define the interleaving aggregate
\[
  \mathrm{Int}(f_1,\dots,f_m)=\sum_{i=1}^{m}\sum_{n\in\mathbb{Z}}c^{(i)}_n q^{\,mn+i},
  \qquad f_i=\sum_n c^{(i)}_n q^n .
\]
Each $f_i$ is recovered by extracting the exponents congruent to $i$ modulo $m$, so $\mathrm{Int}$
is injective; by Theorem~\ref{thm:sym} it is therefore not permutation-invariant for $m\ge2$.
\end{theorem}

\begin{corollary}[Aggregation dichotomy]
For $m\ge2$, a scalar aggregate of a family of $m$ class-indexed series may be permutation-invariant
or injective, but never both.
\end{corollary}

\section{Algorithms}

\paragraph{Moments and orbit counts.} For a permutation group $G\le\Sym(X)$ given elementwise,
Theorem~\ref{thm:moment} computes $\#(X^k/G)$ in $O(|G|\,|X|)$ time --- compute $\varphi(g)=|X^g|$
for each $g$, then return $\frac1{|G|}\sum_g\varphi(g)^k$ --- rather than $O(|G|\,|X|^k)$ for a
union--find over $X^k$. Exactness of the division is a built-in correctness check.

\paragraph{Deciding $k$-transitivity.} By Theorem~\ref{thm:bellcrit} it suffices to compare
$\sum_g\varphi(g)^k$ with $B_k|G|$, with $B_k$ obtained from $B_{k+1}=\sum_{j}\binom{k}{j}B_j$ or by
enumerating restricted growth functions.

\paragraph{Distribution recovery.} Given $s_k=\sum_g\varphi(g)^k$ for $0\le k\le N$ with
$N\ge\max_g\varphi(g)$, the counting vector $c$ solves the Vandermonde system $\sum_v v^kc_v=s_k$;
exact rational elimination recovers $c$ in $O(N^3)$ operations, and integrality is guaranteed by
Theorem~\ref{thm:inversion}.

\section{Discussion}

\subsection{What the bridge connects}
Three a priori unrelated bodies of data are identified: the moments $\sum_g|X^g|^k$ of the
permutation character (the coefficientwise moments of the trace series family); the Bell numbers
$B_k$, realized as counts of restricted growth functions; and permutation-group data --- transitivity
degree, orbit counts on tuples, and the distribution of orbits over coincidence patterns. The
dictionary is exact in both directions.

\subsection{Relation to the classical picture}
For a genuine graded module the counting identity $|(X^k)^g|=|X^g|^k$ linearizes to
$\tr(g\mid V^{\otimes k})=\tr(g\mid V)^k$, so the general form of Theorem~\ref{thm:moment} is
\[
  \frac1{|G|}\sum_{g\in G}\tr(g\mid V)^k=\dim\bigl((V^{\otimes k})^{G}\bigr),
\]
which for $V=\mathbb{C}[X]$ equals $\#(X^k/G)$. The moment hierarchy is thus the permutation shadow
of tensor-power invariant dimensions, and the Bell numbers appear because for a $k$-transitive group
the invariants of $\mathbb{C}[X]^{\otimes k}$ are spanned by the $B_k$ diagonal classes.

\subsection{The product slogan}
The strong claim that the product of all McKay--Thompson series is a holomorphic modular form of
weight $|M|/24$ determining the Monster's character table fails for several independently sufficient
reasons: the pole order is $-194$ (or $-|M|$, depending on the reading of ``all $g$''), so the object
is meromorphic at the cusp (Theorem~\ref{thm:pole}); after renormalization every order-$0$ series
arises, so the construction imposes no constraint (Theorem~\ref{thm:surj}); McKay--Thompson series
are weight-$0$ modular functions for various genus-zero groups, so no weight $|M|/24$ and no common
invariance group is supplied; and, decisively, a permutation-invariant aggregate cannot be injective
(Theorem~\ref{thm:sym}), so no reconstruction map can recover the family from the product. Faithful
aggregation requires labels.

\subsection{Limitations}
The theory is about finite actions and formal series; it says nothing about modularity or
vertex-operator structure. The Bell criterion needs $k\le|X|$; the inversion theorem needs an a
priori bound on the values, and the range is sharp. Theorem~\ref{thm:klein} delimits the whole
moment tower: it is blind to the kernel of the action.

\section{Future work}
\begin{enumerate}
  \item Prove the tensor-power moment hierarchy for complex graded characters and the corresponding
        Bell-type bound for permutation modules.
  \item Develop weights and multipliers for trace series of graded actions and identify which graded
        actions yield genuinely modular series.
  \item Verify coefficient decompositions against a provenance-checked Monster character table and
        the $194$ normalized McKay--Thompson series by exact integer arithmetic, stating modularity
        per class with its actual moonshine group.
  \item Study the fibre spectrum $(m_P)_{P\in\Pat(k)}$ as a finer invariant than $\#(X^k/G)$: which
        spectra occur, and for which classes of actions is the full family of spectra complete?
  \item Characterize the minimal labelling needed for an injective aggregate of class-indexed series.
\end{enumerate}

\appendix
\section{Worked examples}

\begin{example}[$S_4$ on four points]
Fixed-point counts: $4$ (identity), $2$ (six transpositions), $0$ (three double transpositions), $1$
(eight $3$-cycles), $0$ (six $4$-cycles). Then $\sum=24=B_1\cdot24$, $\sum(\cdot)^2=48=B_2\cdot24$,
$\sum(\cdot)^3=120=B_3\cdot24$, $\sum(\cdot)^4=360=B_4\cdot24$: the action is $4$-transitive.
\end{example}

\begin{example}[$C_4$ on four points]
Fixed-point counts $4,0,0,0$. The first moment is $4=B_1\cdot4$ (transitive) but the second is
$16$ against $B_2\cdot4=8$, so $D_2=8=4\cdot 2$: the distinct-coordinate pattern splits into three
orbits and the diagonal pattern into one, giving $\sum_P(m_P-1)=2$.
\end{example}

\begin{example}[Klein blind spot]
Both Klein actions on two points have fixed-point multiset $\{2,2,0,0\}$, hence identical moments
and orbit counts $\#(X^k/V)=2^{k-1}$, yet they are non-isomorphic.
\end{example}

\begin{example}[A $194$-fold product]
If each $f_i$ has order $-1$, then $\prod_{i=1}^{194}f_i$ has order $-194$ and
$q^{194}\prod_i f_i$ has order $0$; conversely any prescribed order-$0$ series is realized by
$f_1=q^{-1}F$, $f_i=q^{-1}$ for $i\ge2$.
\end{example}

