"""Algorithm 2: deciding k-transitivity from a single moment (Bell criterion).

An action of G on X with k <= |X| is k-transitive if and only if
    sum_{g in G} |X^g|^k = B_k * |G|,
with B_k the k-th Bell number. This replaces an orbit computation on the
|X|(|X|-1)...(|X|-k+1) injective tuples by one linear pass over the group,
costing O(|G| * |X| + k^2) arithmetic operations.
"""

from __future__ import annotations

from itertools import permutations, product
from math import comb
from typing import List, Sequence, Tuple

Perm = Tuple[int, ...]


def bell_numbers(k_max: int) -> List[int]:
    """B_0, ..., B_{k_max} via B_{m+1} = sum_j binom(m, j) B_j, in O(k^2)."""
    b: List[int] = [1]
    for m in range(k_max):
        b.append(sum(comb(m, j) * b[j] for j in range(m + 1)))
    return b


def is_k_transitive_by_moment(group: Sequence[Perm], k: int) -> bool:
    """Decide k-transitivity by comparing the k-th moment with B_k |G|."""
    moment = sum(sum(1 for i, gi in enumerate(g) if gi == i) ** k for g in group)
    return moment == bell_numbers(k)[k] * len(group)


def transitivity_degree(group: Sequence[Perm], n: int) -> int:
    """The largest k <= n for which the action is k-transitive (0 if none)."""
    degree = 0
    for k in range(1, n + 1):
        if is_k_transitive_by_moment(group, k):
            degree = k
        else:
            break  # the hierarchy is monotone decreasing
    return degree


def is_k_transitive_bruteforce(group: Sequence[Perm], n: int, k: int) -> bool:
    """Reference implementation: can one injective k-tuple reach all others?"""
    injective = [t for t in product(range(n), repeat=k) if len(set(t)) == k]
    if not injective:
        return True
    reachable = {tuple(g[x] for x in injective[0]) for g in group}
    return all(t in reachable for t in injective)


if __name__ == "__main__":
    groups = {
        "S_5": [tuple(p) for p in permutations(range(5))],
        "AGL(1,5)": [tuple((a * x + b) % 5 for x in range(5)) for a in range(1, 5) for b in range(5)],
        "C_5": [tuple((i + s) % 5 for i in range(5)) for s in range(5)],
    }
    for name, grp in groups.items():
        deg = transitivity_degree(grp, 5)
        checks = [is_k_transitive_by_moment(grp, k) == is_k_transitive_bruteforce(grp, 5, k)
                  for k in range(1, 6)]
        print(f"{name}: transitivity degree {deg}, criterion matches brute force: {all(checks)}")
